# owner: platform
"""Plain text absence notices for parents."""

from typing import List, Sequence

from rosterkit.models import Mark, Student


def _check_owner(student: Student, marks: Sequence[Mark]):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark belongs to {mark.student_id}"
            )


def _compose(student: Student, days: List) -> str:
    dates = ", ".join(day.isoformat() for day in days)
    return (
        f"{student.first_name} {student.last_name} missed "
        f"{len(days)} day(s) of school: {dates}."
    )


# ---
def build_absence_notice(student, marks) -> str:
    """Write a notice naming the student and absent days."""
    _check_owner(student, marks)
    absent = [m for m in marks if m.status == "absent"]
    if not absent:
        raise ValueError("no absences to report")
    return _compose(student, sorted(m.day for m in absent))
